using System.Windows; using System.Windows.Input; using Reforged.App.Commands; using Reforged.App.Services;
namespace Reforged.App.ViewModels;
public sealed class MainWindowViewModel : ViewModelBase { private readonly IWorkspaceManager _workspaces; private readonly IReforgedHostController _host; private object? _activeView; private string _activeTitle="Home"; public object? ActiveView{get=>_activeView;private set=>Set(ref _activeView,value);} public string ActiveTitle{get=>_activeTitle;private set=>Set(ref _activeTitle,value);} public string HostState=>$"Host: {_host.StatusMessage}"; public string ConnectionState=>_host.State==Models.HostControllerState.Running?"Connection: Local":"Connection: Offline"; public string SessionState=>$"Sessions: {_host.ConnectedSessionCount}"; public ICommand NavigateCommand{get;} public ICommand ExitCommand{get;} public MainWindowViewModel(IWorkspaceManager workspaces,IReforgedHostController host){_workspaces=workspaces;_host=host;NavigateCommand=new ParameterCommand(async p=>await _workspaces.ActivateAsync(p?.ToString()??"home"));ExitCommand=new RelayCommand(()=>Application.Current.MainWindow?.Close());_workspaces.ActiveWorkspaceChanged+=(_,_)=>Refresh();_host.StateChanged+=(_,_)=>{Raise(nameof(HostState));Raise(nameof(ConnectionState));Raise(nameof(SessionState));};} private void Refresh(){ActiveView=_workspaces.ActiveWorkspace?.View;ActiveTitle=_workspaces.ActiveWorkspace?.Title??"Home";} }
